CREATE TABLE stock (product_id UUID PRIMARY KEY, available_quantity INTEGER NOT NULL CHECK (available_quantity >= 0), reserved_quantity INTEGER NOT NULL DEFAULT 0 CHECK (reserved_quantity >= 0), version BIGINT NOT NULL DEFAULT 0, updated_at TIMESTAMP NOT NULL DEFAULT now());
CREATE TABLE inventory_reservation (id UUID PRIMARY KEY, order_id UUID NOT NULL, product_id UUID NOT NULL, quantity INTEGER NOT NULL CHECK (quantity > 0), status VARCHAR(32) NOT NULL, expires_at TIMESTAMP NOT NULL, version BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMP NOT NULL DEFAULT now(), UNIQUE(order_id, product_id));
